-- Sohaib Masood personal portfolio dump. SQLite first.
BEGIN;
CREATE TABLE IF NOT EXISTS "Project" (
  "id" TEXT PRIMARY KEY,
  "title" TEXT NOT NULL,
  "slug" TEXT NOT NULL UNIQUE,
  "shortDesc" TEXT NOT NULL,
  "longDesc" TEXT NOT NULL,
  "techStack" TEXT NOT NULL,
  "features" TEXT NOT NULL,
  "screenshots" TEXT NOT NULL DEFAULT '[]',
  "thumbnail" TEXT,
  "githubUrl" TEXT,
  "liveUrl" TEXT,
  "demoVideoUrl" TEXT,
  "proofAsset" TEXT,
  "guardrails" TEXT NOT NULL DEFAULT '[]',
  "status" TEXT NOT NULL DEFAULT 'live',
  "featured" INTEGER NOT NULL DEFAULT 0,
  "accentColor" TEXT NOT NULL DEFAULT '#7C3AED',
  "architecture" TEXT,
  "category" TEXT NOT NULL DEFAULT 'ai-agent',
  "order" INTEGER NOT NULL DEFAULT 0,
  "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "Setting" (
  "id" TEXT PRIMARY KEY,
  "key" TEXT NOT NULL UNIQUE,
  "value" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS "SiteContent" (
  "id" TEXT PRIMARY KEY,
  "section" TEXT NOT NULL UNIQUE,
  "data" TEXT NOT NULL,
  "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
);
INSERT OR REPLACE INTO "Project" ("id","title","slug","shortDesc","longDesc","techStack","features","screenshots","thumbnail","githubUrl","liveUrl","demoVideoUrl","proofAsset","guardrails","status","featured","accentColor","architecture","category","order","updatedAt") VALUES ('proj_agriconnect','AgriConnect','agriconnect','Digital agriculture marketplace with deep learning crop disease detection, equipment rentals, and Django backend.','AgriConnect is a comprehensive digital agriculture platform developed as a Final Year Project at COMSATS University. It empowers buyers, farmers, and labor crews with a unified marketplace to trade crops, rent farming machinery, manage farmland access, and hire labor without role friction.

The platform integrates a deep learning leaf disease classification model that allows growers to upload a photo of a diseased leaf and receive instant diagnostics and treatment advice directly within the web app.

Engineered with a robust Django backend, relational database architecture, and a modern responsive interface, AgriConnect delivers practical, end-to-end commerce and field assistance for small-scale farmers.','["Python","Django","Django REST","Keras","Deep Learning","SQLite","Next.js","OpenRouter"]','[{"title":"Digital Marketplace for Crops & Equipment","description":"Buy, sell, and rent machinery and crops with role-based dashboards for buyers, farmers, and labor."},{"title":"Deep Learning Leaf Disease Screening","description":"Upload plant photos to get fast model-based diagnostic feedback without external tools."},{"title":"Farmland Access & Labor Management","description":"Connects small-scale landowners with verified seasonal labor crews to streamline field operations."},{"title":"Digital Wallet & Transaction Ledger","description":"Internal practice wallet balances support seamless order simulation, rentals, and payments."}]','[]','/thumbs/agriconnect.png',NULL,'https://agriconnect-agentic-platform-frontend.onrender.com',NULL,NULL,'["staged-write","human-confirm","audit-ledger"]','live',1,'#10B981','{"title":"How AgriConnect works","layers":[[{"id":"storefront","title":"Shop website","detail":"For buyers","items":["Browse crops and machines","Add to cart and pay"]},{"id":"mcp-entry","title":"Helper bots","detail":"For operators","items":["Ask a bot to buy or rent","Same rules as the website"]}],[{"id":"roles","title":"Who can do what","items":["Buyers, farmers, workers","Each sees the right tools"]},{"id":"commerce","title":"Orders and bookings","items":["Checkout and delivery status","Rent machines or book land"]},{"id":"wallet","title":"Payments","items":["Wallet and deals","Clear payment history"]}],[{"id":"agent-market","title":"Bot actions","items":["Buy, rent, hire, pay","Works like a careful assistant"]},{"id":"agent-ai","title":"Smart checks","items":["Spot plant disease","Suggest fair prices"]}],[{"id":"sqlite","title":"Saved records","items":["Products and orders","Photos and files"]},{"id":"disease-ai","title":"Plant scan","items":["Reads a leaf photo","Returns a simple result"]},{"id":"harden","title":"Security","items":["Passwords and access limits","Secrets stay off the public site"]}]],"note":"People and helper bots share the same shop rules from start to finish."}','web',1,CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "Project" ("id","title","slug","shortDesc","longDesc","techStack","features","screenshots","thumbnail","githubUrl","liveUrl","demoVideoUrl","proofAsset","guardrails","status","featured","accentColor","architecture","category","order","updatedAt") VALUES ('proj_smart-ai-doctor','Smart AI Doctor','smart-ai-doctor','LLM-based medical consultation chatbot trained on 250K doctor-patient interactions with DeepSeek R1 & voice synthesis.','Smart AI Doctor is an intelligent healthcare assistant designed to streamline preliminary medical consultations and patient triage. Trained on a curated dataset of over 250,000 real-world doctor-patient interactions, it leverages DeepSeek R1 reasoning to evaluate symptoms and formulate structured clinical summaries.

To ensure complete accessibility, the application integrates bidirectional speech synthesis — speech-to-text input so patients can describe concerns naturally, and realistic text-to-speech output explaining potential diagnoses and recommended precautions.

The system includes strict safety boundaries, ensuring it never prescribes controlled medication while providing reliable guidance before clinical visits.','["Python","DeepSeek R1","Speech-to-Text","Text-to-Speech","LangChain","FastAPI","Transformers"]','[{"title":"Trained on 250K Medical Consultations","description":"Fine-tuned reasoning engine capable of understanding diverse symptom descriptions and nuanced patient histories."},{"title":"Voice-Driven Consultation (STT / TTS)","description":"Hands-free conversational interaction allowing elderly or vision-impaired patients to describe ailments naturally."},{"title":"Clinical Triage & Symptom Evaluation","description":"Maps spoken complaints into prioritized severity tiers and structured visit summaries for healthcare staff."},{"title":"Safety Boundaries & Disclaimers","description":"Enforces rigorous guardrails against self-medication and flags high-risk emergencies immediately."}]','[]','/thumbs/medcare.png',NULL,NULL,NULL,NULL,'[]','live',1,'#0EA5E9','"Voice Input → DeepSeek R1 Engine → Structured Clinical Triage"','ai-agent',2,CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "Project" ("id","title","slug","shortDesc","longDesc","techStack","features","screenshots","thumbnail","githubUrl","liveUrl","demoVideoUrl","proofAsset","guardrails","status","featured","accentColor","architecture","category","order","updatedAt") VALUES ('proj_smart-islamic-guider','Smart Islamic Guider','smart-islamic-guider','RAG-powered Islamic QA chatbot trained on Sihah Sitta and the Quran using Python, LangChain, and LLaMA 3 on Groq.','Developed as a semester project at COMSATS University, Smart Islamic Guider provides authentic, context-verified Islamic answers to religious and theological questions. The assistant is trained on authoritative reference texts including the Quran and the Sihah Sitta Hadith collections.

It utilizes a Retrieval-Augmented Generation (RAG) architecture powered by LangChain and high-speed LLaMA 3 inference on the Groq Cloud API. When a user asks a query, relevant verses and Hadith citations are retrieved through vector embeddings, ensuring responses are grounded directly in authentic sources with zero hallucination.

The system provides citation references for each answered question, giving users immediate access to verified chapter and verse numbers.','["Python","LangChain","LLaMA 3","Groq Cloud API","RAG","FAISS","Hugging Face"]','[{"title":"RAG over Sihah Sitta & Quran","description":"Semantic vector indexing over authentic Hadith collections and scripture for hallucination-free retrieval."},{"title":"Ultra-Fast Groq Cloud Inference","description":"Sub-second response generation utilizing LLaMA 3 running on Groq''s high-speed LPU infrastructure."},{"title":"Precise Citations & Source Proofs","description":"Every generated response links directly to referenced Surah verses or Hadith volume and book numbers."},{"title":"Conversational QA Context","description":"Maintains multi-turn context allowing follow-up queries and clarification on complex theological topics."}]','[]','/thumbs/islamic_guider.png',NULL,NULL,NULL,NULL,'[]','live',1,'#D4A853','"Query → Vector Retrieval (FAISS) → LLaMA 3 (Groq) → Grounded Answer"','ai-agent',3,CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "Project" ("id","title","slug","shortDesc","longDesc","techStack","features","screenshots","thumbnail","githubUrl","liveUrl","demoVideoUrl","proofAsset","guardrails","status","featured","accentColor","architecture","category","order","updatedAt") VALUES ('proj_ai-automation-suite','AI Automation Suite','ai-automation-suite','Agentic AI automation infrastructure combining voice agents, multi-agent pipelines, Claude MCP integrations, UiPath RPA, and n8n workflows.','A production-grade AI automation infrastructure built to eliminate manual work and speed up business decision-making. The suite combines multiple automation paradigms: real-time voice agents using OpenAI and Vapi for live conversations with tool calling; multi-agent decision pipelines where AI agents coordinate APIs and business platforms; and Claude MCP integrations that give agents secure, standardised access to enterprise data sources.

On the RPA side, UiPath handles deterministic desktop and document workflows, while n8n orchestrates low-code pipelines connecting cloud services and APIs end-to-end. LLM reasoning layers on top of RPA for intelligent document classification and exception handling where rules alone are not enough.

RAG pipelines, structured outputs, and guardrails keep all agent behaviour accurate and production-safe, with logging and retry logic built in from day one.','["OpenAI","Vapi","Claude MCP","LangChain","UiPath","n8n","RAG","Python"]','[{"title":"Real-Time Voice Agents","description":"Live conversation agents built with OpenAI models and Vapi, handling tool calling and low-latency speech interactions."},{"title":"Multi-Agent Decision Pipelines","description":"Coordinate multiple AI agents, APIs, and business platforms to automate complex decision workflows with minimal human intervention."},{"title":"Claude MCP Enterprise Integration","description":"Secure, standardised agent access to enterprise tools and data sources via the Model Context Protocol."},{"title":"Intelligent RPA & n8n Orchestration","description":"Combine deterministic UiPath RPA with LLM reasoning for smart document processing and business workflow automation."}]','[]','/thumbs/automation.png',NULL,NULL,NULL,NULL,'[]','live',1,'#E8536A','"Voice Agent / MCP / n8n → LLM Reasoning → UiPath RPA → Business Platform"','automation',4,CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "Project" ("id","title","slug","shortDesc","longDesc","techStack","features","screenshots","thumbnail","githubUrl","liveUrl","demoVideoUrl","proofAsset","guardrails","status","featured","accentColor","architecture","category","order","updatedAt") VALUES ('proj_dualhire','DualHire','dualhire','Two-sided agentic AI platform where autonomous agents handle candidate search, resume screening, and interview scheduling.','DualHire is an agentic hiring platform where two autonomous AI agents cooperate to complete the hiring cycle. Ava acts on behalf of candidates to format profiles and apply to open roles; Orion represents the hiring team to review qualifications and book interview slots on the company calendar.

The platform demonstrates real-time agent-to-agent collaboration with audit logs, human confirmation guardrails, and transparent telemetry.','["Next.js","Python","OpenAI","Vapi Voice","Playwright","SQLite","SSE"]','[{"title":"Two-Sided Cooperative Agents","description":"Ava applies for candidate; Orion evaluates fit and coordinates calendar availability."},{"title":"Automated Calendar Scheduling","description":"Finds overlapping availability between candidate and interviewer to book verified meetings."},{"title":"Audit Trail & Step-by-Step Replay","description":"Complete transparency into what actions the agents performed and the reasoning behind each step."}]','[]','/thumbs/dualhire.png',NULL,NULL,NULL,NULL,'["staged-write","human-confirm","audit-ledger","resumable"]','live',0,'#3B82F6','{"title":"How DualHire works","layers":[[{"id":"landing","title":"Your dashboard","items":["Sign in as talent or company","See job matches"]},{"id":"live-hub","title":"Live view","items":["Watch the two agents talk","See the final outcome"]}],[{"id":"auth-match","title":"Find a fit","items":["Match people to jobs","Keep profiles safe"]},{"id":"a2a","title":"Agent talk","items":["Candidate agent ↔ company agent","Agree score and interview time"]}],[{"id":"bridge","title":"Apply for you","items":["Opens the career site safely","Submits the agreed packet","Rate limits and CSRF guards"]}],[{"id":"northbridge","title":"Northbridge Careers","items":["Career board","Takes the application"]},{"id":"meridian","title":"Meridian Careers","items":["Second board","Same safe apply flow"]}]],"note":"Two agents negotiate, then a safe helper applies on the career boards."}','ai-agent',5,CURRENT_TIMESTAMP);
