INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_services','services','[{"icon":"Bot","title":"Agentic AI & Voice Pipelines","description":"Design and deploy autonomous AI agents, real-time voice assistants with Vapi & OpenAI, and multi-tool orchestration pipelines with tool calling, MCP integrations, and low-latency interactions.","accent":"#E8536A"},{"icon":"Workflow","title":"LLM, RAG & Fine-Tuning","description":"Build high-precision RAG systems with LangChain, LLaMA 3, FAISS, and vector search. Fine-tune domain-specific models — including OCR models like PP-OCRv4 on custom image datasets.","accent":"#D4A853"},{"icon":"Cpu","title":"AI Automation & RPA","description":"Automate complex business workflows combining LLM reasoning with UiPath RPA and n8n orchestration — for document processing, decision pipelines, and intelligent exception handling.","accent":"#FF7B8A"},{"icon":"Brain","title":"AI System Integration","description":"Connect AI models to enterprise tools and APIs using Claude MCP, structured outputs, and guardrails — making AI components production-safe, observable, and reliably maintainable.","accent":"#1B2A4A"}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_process','process','[{"step":1,"title":"Problem Scoping","description":"Analyse requirements, identify automation opportunities, and select the right AI stack.","icon":"Search"},{"step":2,"title":"Model & System Design","description":"Choose optimal LLMs, vector indexes, agent frameworks, and API architectures.","icon":"PenTool"},{"step":3,"title":"Pipeline Engineering","description":"Build agent pipelines, wire LLM tools, connect APIs, and integrate automation flows.","icon":"Hammer"},{"step":4,"title":"Training & Fine-Tuning","description":"Fine-tune domain models (LLMs, OCR) on curated datasets, run full evaluation cycles.","icon":"ShieldCheck"},{"step":5,"title":"Deployment & Monitoring","description":"Ship to production with logging, retry logic, and real-time telemetry to stay reliable.","icon":"Rocket"},{"step":6,"title":"Optimise & Iterate","description":"Analyse latency, cut token costs, tune guardrails, and continuously improve output quality.","icon":"RefreshCw"}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_why_us','why_us','[{"icon":"Bot","title":"Specialized in Agentic AI","description":"Hands-on experience deploying live voice agents, multi-agent pipelines, and MCP-integrated AI systems in production environments."},{"icon":"Brain","title":"LLM & Fine-Tuning Depth","description":"From RAG pipelines with FAISS and LangChain to full model fine-tuning pipelines (PP-OCRv4, DeepSeek R1) on domain-specific datasets."},{"icon":"Cpu","title":"End-to-End AI Automation","description":"Combine LLM reasoning with UiPath RPA and n8n workflows for intelligent document processing and business automation at scale."},{"icon":"ShieldCheck","title":"Production Mindset","description":"Structured outputs, guardrails, retry logic, and production monitoring built into every AI system from day one."}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_testimonials','testimonials','[{"quote":"Sohaib developed real-time voice agents and automated Playwright pipelines that significantly accelerated our engineering workflows. Outstanding grasp of modern AI.","name":"Engineering Lead","role":"Octathorn Technologies","rating":5},{"quote":"His final year project AgriConnect combined a complex Django marketplace with deep learning crop disease detection seamlessly. Diligent, resourceful, and technically sound.","name":"Project Supervisor","role":"COMSATS University","rating":5},{"quote":"Quickly integrated RAG pipelines and Hugging Face NLP models during his internship. An engineer who genuinely loves solving difficult software problems.","name":"Technical Mentor","role":"Eziline Software House","rating":5}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_faqs','faqs','[{"question":"What are your core technical specializations?","answer":"My primary expertise is Agentic AI, Generative AI, LLM Engineering, and AI Automation. I work hands-on with OpenAI models, Vapi voice AI, LangChain, Claude MCP, UiPath RPA, and n8n workflow automation."},{"question":"Have you worked on model training and fine-tuning?","answer":"Yes. I am currently fine-tuning PP-OCRv4 on a custom 24K-image dataset of specific font styles, running the full pipeline from data preprocessing, model training, and evaluation to production-ready export. I have also fine-tuned DeepSeek R1 on 250K medical consultation records."},{"question":"What projects have you built?","answer":"Key projects include AgriConnect (agriculture marketplace with deep learning disease detection), Smart AI Doctor (medical LLM chatbot with voice synthesis), Smart Islamic Guider (RAG over Quran & Hadith), and DualHire (two-agent agentic hiring platform)."},{"question":"Are you available for contract or full-time roles?","answer":"Yes, I am open to innovative AI engineering roles, high-impact consulting, and agentic AI development opportunities. Reach out via email or LinkedIn."}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_tech_advanced','tech_advanced','[{"name":"Python","color":"#3776AB"},{"name":"LangChain","color":"#E8536A"},{"name":"OpenAI","color":"#10B981"},{"name":"Vapi Voice AI","color":"#D4A853"},{"name":"LLaMA 3","color":"#8B5CF6"},{"name":"DeepSeek R1","color":"#3B82F6"},{"name":"Transformers","color":"#FBBF24"},{"name":"FastAPI","color":"#009688"},{"name":"Node.js","color":"#339933"},{"name":"React / Next.js","color":"#61DAFB"},{"name":"Django & REST","color":"#092E20"}]',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_tech_shipping','tech_shipping','[{"name":"Claude MCP","color":"#D97706"},{"name":"UiPath RPA","color":"#FA4616"},{"name":"n8n Workflows","color":"#EA4B71"},{"name":"PaddleOCR / PP-OCRv4","color":"#E8536A"},{"name":"FAISS & Vector DBs","color":"#EC4899"},{"name":"Playwright","color":"#2EAD33"},{"name":"AWS EC2","color":"#FF9900"},{"name":"Linux / Ubuntu","color":"#E95420"},{"name":"Docker","color":"#2496ED"},{"name":"PostgreSQL & MySQL","color":"#336791"}]',CURRENT_TIMESTAMP);
