INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_about_story','about_story','{"paragraphs":["I am an AI Engineer based in Islamabad, Pakistan, specializing in Generative AI, Agentic Systems, and intelligent automation. My work spans building real-time voice agents, multi-agent pipelines, RAG-based chatbots, and fine-tuning domain-specific models — turning advanced AI research into production-ready systems.","Currently at Octathorn Technologies as an AI Automation Engineer, I design agentic AI solutions using OpenAI, Vapi, Claude MCP, LangChain, UiPath, and n8n. I am also running a full fine-tuning pipeline for PP-OCRv4 on a 24K-image custom font dataset — from data preprocessing and model training through evaluation and export.","I graduated with a BS in Software Engineering from COMSATS University (CGPA 3.21). My portfolio includes AgriConnect (deep learning crop disease detection + marketplace), Smart AI Doctor (DeepSeek R1 medical chatbot with voice synthesis), Smart Islamic Guider (LLaMA 3 RAG over Quran & Hadith), and DualHire (two-agent agentic hiring platform)."]}',CURRENT_TIMESTAMP);
INSERT OR REPLACE INTO "SiteContent" ("id","section","data","updatedAt") VALUES ('content_about_milestones','about_milestones','[{"year":"Feb 2026 – Present","title":"AI Automation Engineer — Octathorn Technologies","description":"Design and deploy agentic AI systems, real-time voice agents (Vapi & OpenAI), multi-agent decision pipelines, Claude MCP integrations, and UiPath/n8n automation. Currently fine-tuning PP-OCRv4 on a 24K-image custom font dataset — full pipeline from training to evaluation.","icon":"Bot","accent":"#E8536A"},{"year":"Sep 2025 – Jan 2026","title":"Automation Engineer Intern — Octathorn Technologies","description":"Cross-browser automation with Playwright, Ubuntu Linux cloud management on AWS EC2, and desktop RPA with UiPath via RDP.","icon":"Cpu","accent":"#D4A853"},{"year":"Jan 2025 – Apr 2025","title":"Python Developer Intern — Eziline Software House","description":"Built LLM chatbots with LangChain & LLaMA 3, integrated RAG pipelines and FAISS vector search, deployed NLP and disease detection models via Flask APIs.","icon":"Code","accent":"#1B2A4A"},{"year":"March 2025","title":"BS Software Engineering — COMSATS University","description":"CGPA 3.21. Majors: Artificial Intelligence, Machine Learning, Data Mining, and Algorithms.","icon":"Award","accent":"#10B981"},{"year":"Dec 2024","title":"AgriConnect — Final Year Project","description":"Digital agriculture marketplace with deep learning crop disease screening, multi-role dashboards, and digital wallet. Built with Python, Keras, and Django.","icon":"Package","accent":"#E8536A"}]',CURRENT_TIMESTAMP);
COMMIT;
